#!/usr/bin/env python3
"""
ExploreSuriname.com - Full Tourism & News Site Generator
Generates: index.html, activities.html (Things to Do; nature.html is a stub),
           restaurants.html, hotels.html, currency.html, news.html,
           sitemap.xml, robots.txt
Run daily via GitHub Actions.
"""

import feedparser
import html as html_lib
import re, os, json
import concurrent.futures as cf
from pathlib import Path
import urllib.request, urllib.parse
from datetime import datetime, timezone, timedelta

SITE_URL       = "https://exploresuriname.com"
CONTACT_EMAIL  = "contact@exploresuriname.com"
# Cloudflare Turnstile site key for the public submission form. Empty = widget
# off (honeypot + per-IP rate limit still apply). Secret lives on the Worker.
TURNSTILE_SITEKEY = "0x4AAAAAAEA9rqn_-t206NGg"
SR_TZ          = timezone(timedelta(hours=-3))   # Suriname time (UTC-3, no DST)
YEAR           = datetime.now(SR_TZ).year
MAX_PER_FEED   = 10

# Load OSM enrichment cache (produced by enrich_from_osm.py, committed periodically)
# Keys: slug → {opening_hours, phone, address, cuisine, price_range, ...}
# Format: slug-keyed dict (new) OR legacy list-of-dicts (old) — both handled below
_ENRICHMENTS: dict = {}
_enrich_path = Path(__file__).parent / "listing_enrichments.json"
if _enrich_path.exists():
    try:
        _raw = json.loads(_enrich_path.read_text(encoding="utf-8"))
        if isinstance(_raw, dict):
            _ENRICHMENTS = _raw                          # new slug-keyed format
        else:
            for _e in _raw:                              # legacy list format
                if _e.get("found"):
                    _ENRICHMENTS[_e["slug"]] = _e
        print(f"  Loaded {len(_ENRICHMENTS)} OSM enrichments from listing_enrichments.json")
    except Exception as _err:
        print(f"  Warning: could not load listing_enrichments.json — {_err}")

# Load Foursquare enrichment cache (produced by scripts/fetch_foursquare.py, committed manually)
# Keys: slug → {name, address, phone, website, lat, lng, score, matched, ...}
_FSQ: dict = {}
_fsq_path = Path(__file__).parent / "foursquare_cache.json"
if _fsq_path.exists():
    try:
        _fsq_raw = json.loads(_fsq_path.read_text(encoding="utf-8"))
        _FSQ = {k: v for k, v in _fsq_raw.items() if v.get("matched")}
        print(f"  Loaded {len(_FSQ)} Foursquare matches from foursquare_cache.json")
    except Exception as _err:
        print(f"  Warning: could not load foursquare_cache.json — {_err}")

# Load Foursquare details cache (produced by scripts/fetch_foursquare_details.py, committed manually)
# Keys: slug → {hours_display, photo_url, phone, website}
# Priority in generate.py: Google Places (future) > OSM > Foursquare
_FSQ_DETAILS: dict = {}
_fsq_det_path = Path(__file__).parent / "foursquare_details_cache.json"
if _fsq_det_path.exists():
    try:
        _FSQ_DETAILS = json.loads(_fsq_det_path.read_text(encoding="utf-8"))
        _det_hours = sum(1 for v in _FSQ_DETAILS.values() if v.get("hours_display"))
        _det_photo = sum(1 for v in _FSQ_DETAILS.values() if v.get("photo_url"))
        print(f"  Loaded {len(_FSQ_DETAILS)} FSQ details ({_det_hours} hours, {_det_photo} photos)")
    except Exception as _err:
        print(f"  Warning: could not load foursquare_details_cache.json — {_err}")

# Single source of truth: load all listing data from exploresuriname_listings.json
_jd_path = Path(__file__).parent / "exploresuriname_listings.json"
_BIZ: dict = {}          # slug → full entry dict (name, location, address, phone, website, description …)
_JSON_DESCS: dict = {}   # slug → description  (kept for build_listing_page fallback reference)
if _jd_path.exists():
    try:
        for _e in json.loads(_jd_path.read_text(encoding="utf-8")):
            _slug = _e.get("slug")
            if not _slug: continue
            _BIZ[_slug] = _e
            if _e.get("description", "").strip():
                _JSON_DESCS[_slug] = _e["description"].strip()
        print(f"  Loaded {len(_BIZ)} listings from exploresuriname_listings.json")
    except Exception as _err:
        print(f"  Warning: could not load listing data — {_err}")

# ── Listing overrides from the admin panel (D1, read via leaderboard Worker) ────
# Admin panel: https://esr-admin.surinamedomains.workers.dev (Cloudflare Access).
# Overrides win over JSON; applied before anything reads _BIZ. Build never fails
# on backend trouble — it just ships without overrides.
_OVR_FIELDS = ("description", "website", "phone", "address")
_OVR_URL = "https://esr-leaderboard.surinamedomains.workers.dev/overrides"
_OVERRIDES: dict = {}
try:
    import urllib.request as _ureq
    _ovr_req = _ureq.Request(_OVR_URL, headers={"User-Agent": "ExploreSR-build/1.0"})
    with _ureq.urlopen(_ovr_req, timeout=15) as _ovr_r:
        _OVERRIDES = json.loads(_ovr_r.read().decode("utf-8"))
    _ovr_applied = 0
    for _oslug, _o in _OVERRIDES.items():
        if _oslug in _BIZ and isinstance(_o, dict):
            for _ok in _OVR_FIELDS:
                if isinstance(_o.get(_ok), str):
                    _BIZ[_oslug][_ok] = _o[_ok].strip()
            _ovr_applied += 1
    print(f"  Applied {_ovr_applied} listing overrides from admin panel")
except Exception as _err:
    print(f"  Warning: listing overrides unavailable — {_err}")

# Featured listings are driven entirely from the admin panel (Listings tab →
# "Featured listing" checkbox + priority). slug -> rank, where a lower rank
# sorts first and 999 means "featured but unranked".
_ADMIN_FEATURED: dict = {}
for _oslug, _o in _OVERRIDES.items():
    if isinstance(_o, dict) and _o.get("featured"):
        try:
            _rank = int(_o.get("feat_rank") or 0)
        except (TypeError, ValueError):
            _rank = 0
        _ADMIN_FEATURED[_oslug] = _rank if 1 <= _rank <= 999 else 999
if _ADMIN_FEATURED:
    print(f"  Featured listings from admin panel: {len(_ADMIN_FEATURED)}")

# ── Approved public submissions (Add your business form) ──────────────────────
# Anyone can propose a listing at /submit-business.html. Nothing is published
# until it is approved in the admin panel; approved rows arrive here and are
# injected into the same structures the repo listings use, so once live a
# submitted listing is indistinguishable from a curated one.
# A repo listing ALWAYS wins: a submission can never overwrite curated data.
# Build never fails on backend trouble — it just ships without them.
_SUB_URL = "https://esr-leaderboard.surinamedomains.workers.dev/listings/approved"
_SUB_LIST_KEY = {"restaurant": "RESTAURANTS", "hotel": "HOTELS", "shopping": "SHOPPING",
                 "service": "SERVICES", "adventure": "ADVENTURES_BIZ", "sightseeing": "SIGHTSEEING"}
_SUB_BY_CAT: dict = {_k: [] for _k in _SUB_LIST_KEY}
_SUB_IMGS: dict = {}      # slug -> image url, merged into _IMGS below
_SUB_SUBCAT: dict = {}    # slug -> chip key, consulted first by _subcat()
try:
    import urllib.request as _ureq
    _sub_req = _ureq.Request(_SUB_URL, headers={"User-Agent": "ExploreSR-build/1.0"})
    with _ureq.urlopen(_sub_req, timeout=15) as _sub_r:
        _sub_rows = json.loads(_sub_r.read().decode("utf-8"))
    _sub_skipped = 0
    for _s in (_sub_rows if isinstance(_sub_rows, list) else []):
        _sslug = (_s.get("slug") or "").strip()
        _scat  = _s.get("category") or ""
        if not _sslug or _sslug in _BIZ or _scat not in _SUB_LIST_KEY:
            _sub_skipped += 1
            continue
        _BIZ[_sslug] = {"slug": _sslug, "name": _s.get("name", ""), "category": "",
                        "description": _s.get("description", ""),
                        "location": _s.get("location") or "Suriname",
                        "address": _s.get("address", ""), "phone": _s.get("phone", ""),
                        "website": _s.get("website", ""), "email": _s.get("email", ""),
                        "main_image": _s.get("image", ""), "submitted": True}
        if (_s.get("description") or "").strip():
            _JSON_DESCS[_sslug] = _s["description"].strip()
        if _s.get("image"):  _SUB_IMGS[_sslug]   = _s["image"]
        if _s.get("subcat"): _SUB_SUBCAT[_sslug] = _s["subcat"]
        _SUB_BY_CAT[_scat].append(_sslug)
    print(f"  Added {sum(len(_v) for _v in _SUB_BY_CAT.values())} approved submissions"
          + (f" ({_sub_skipped} skipped)" if _sub_skipped else ""))
except Exception as _err:
    print(f"  Warning: approved submissions unavailable — {_err}")

