def _biz_url(b):
    import re as _re
    w = b.get('website', '')
    if w and _re.match(r'^(https?://|www\.)[^\s@+]{4,}\.[a-z]{2,}', w, _re.I):
        return ('https://' + w) if not w.startswith('http') else w
    return f"https://www.google.com/search?q={urllib.parse.quote(b['name'] + ' Suriname')}"

