    import json as _json
    nat_ld = {
        "@context":    "https://schema.org",
        "@type":       "TouristAttraction",
        "name":        name,
        "url":         page_url,
        "description": desc if desc else name + ". Nature attraction in Suriname.",
        "geo":         {"@type": "GeoCoordinates", "addressCountry": "SR"},
    }
    if tags:
        nat_ld["keywords"] = ", ".join(tags)
